import pynwb
import numpy as np
import os

nwb_path = '/app/data/sub-440956/sub-440956_ses-20190207T120657_behavior+ecephys+ogen.nwb'

with pynwb.NWBHDF5IO(nwb_path, 'r') as io:
    nwb = io.read()

    # Trials table
    print("=== Trials ===")
    print(f"N trials: {len(nwb.intervals['trials'])}")
    trials = nwb.intervals['trials']

    for col in trials.colnames:
        try:
            vals = trials[col][:]
            if isinstance(vals[0], str):
                unique_vals, counts = np.unique(vals, return_counts=True)
                print(f"  {col}: {dict(zip(unique_vals, counts))}")
            elif isinstance(vals[0], (int, float, np.integer, np.floating)):
                unique_vals = np.unique(vals[~np.isnan(vals)]) if np.issubdtype(type(vals[0]), np.floating) else np.unique(vals)
                if len(unique_vals) <= 20:
                    print(f"  {col}: unique={unique_vals}, counts={[np.sum(vals==v) for v in unique_vals]}")
                else:
                    print(f"  {col}: min={np.nanmin(vals):.4f}, max={np.nanmax(vals):.4f}, mean={np.nanmean(vals):.4f}, n_unique={len(unique_vals)}")
            else:
                print(f"  {col}: type={type(vals[0])}, first={vals[0]}")
        except Exception as e:
            print(f"  {col}: error - {e}")

    # Look at processing modules
    print("\n=== Processing Modules ===")
    if nwb.processing:
        for name, mod in nwb.processing.items():
            print(f"  Module: {name}")
            for container_name in mod.data_interfaces:
                container = mod.data_interfaces[container_name]
                print(f"    {container_name}: {type(container).__name__}")
                if hasattr(container, 'columns'):
                    print(f"      columns: {[c.name for c in container.columns]}")

    # Look at acquisition
    print("\n=== Acquisition ===")
    for name, ts in nwb.acquisition.items():
        print(f"  {name}: {type(ts).__name__}")
        if hasattr(ts, 'data'):
            print(f"    data shape: {ts.data.shape if hasattr(ts.data, 'shape') else 'N/A'}")
            print(f"    timestamps: {ts.timestamps[:5] if ts.timestamps is not None else 'None'}")
            if hasattr(ts, 'description'):
                print(f"    description: {ts.description}")

